const snapshotPrices = `-- name: SnapshotPrices :many
SELECT p.variant_id, p.price_list_id, p.min_qty, p.price, nlevel(ou.path)::int AS depth, ou.name AS source_name, p.effective_from, p.effective_to
FROM prices p
JOIN org_units ou ON ou.id = p.org_unit_id
JOIN org_units t ON t.id = $1
JOIN price_lists pl ON pl.id = p.price_list_id AND pl.status = 'active'
WHERE p.company_id = $2 AND t.path <@ ou.path
  AND (p.effective_to IS NULL OR p.effective_to > $3::timestamptz)
ORDER BY p.variant_id, p.price_list_id, p.min_qty, p.effective_from
`

type SnapshotPricesParams struct {
	StoreOrgUnitID uuid.UUID `json:"store_org_unit_id"`
	CompanyID      uuid.UUID `json:"company_id"`
	Since          time.Time `json:"since"`
}

type SnapshotPricesRow struct {
	VariantID     uuid.UUID       `json:"variant_id"`
	PriceListID   uuid.UUID       `json:"price_list_id"`
	MinQty        decimal.Decimal `json:"min_qty"`
	Price         decimal.Decimal `json:"price"`
	Depth         int32           `json:"depth"`
	SourceName    string          `json:"source_name"`
	EffectiveFrom time.Time       `json:"effective_from"`
	EffectiveTo   *time.Time      `json:"effective_to"`
}

// Only prices set at the store's org unit or one of its ancestors (the only ones that can ever apply to this store),
// still open or ending in the future, on active lists. depth = nlevel(path) so the edge can pick "nearest wins".
func (q *Queries) SnapshotPrices(ctx context.Context, arg SnapshotPricesParams) ([]SnapshotPricesRow, error) {
	rows, err := q.db.Query(ctx, snapshotPrices, arg.StoreOrgUnitID, arg.CompanyID, arg.Since)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SnapshotPricesRow{}
	for rows.Next() {
		var i SnapshotPricesRow
		if err := rows.Scan(
			&i.VariantID,
			&i.PriceListID,
			&i.MinQty,
			&i.Price,
			&i.Depth,
			&i.SourceName,
			&i.EffectiveFrom,
			&i.EffectiveTo,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const snapshotPromotions = `-- name: SnapshotPromotions :many
SELECT p.id, p.company_id, p.code, p.name, p.description, p.type, p.config, p.priority, p.stackable, p.exclusive, p.starts_at, p.ends_at, p.days_of_week, p.time_from, p.time_to, p.status, p.version, p.created_by, p.created_at, p.updated_at FROM promotions p
WHERE p.company_id = $1 AND p.status = 'active' AND (p.ends_at IS NULL OR p.ends_at > $2::timestamptz)
  AND (NOT EXISTS (SELECT 1 FROM promotion_scopes s WHERE s.promotion_id = p.id AND s.scope_type = 'org_unit')
       OR EXISTS (SELECT 1 FROM promotion_scopes s JOIN org_units so ON so.id = s.scope_id JOIN org_units t ON t.id = $3
                  WHERE s.promotion_id = p.id AND s.scope_type = 'org_unit' AND t.path <@ so.path))
ORDER BY p.id
`

type SnapshotPromotionsParams struct {
	CompanyID      uuid.UUID `json:"company_id"`
	At             time.Time `json:"at"`
	StoreOrgUnitID uuid.UUID `json:"store_org_unit_id"`
}

// Everything that has not ended and applies to this store (future starts included: the edge may sell after they begin).
func (q *Queries) SnapshotPromotions(ctx context.Context, arg SnapshotPromotionsParams) ([]Promotion, error) {
	rows, err := q.db.Query(ctx, snapshotPromotions, arg.CompanyID, arg.At, arg.StoreOrgUnitID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Promotion{}
	for rows.Next() {
		var i Promotion
		if err := rows.Scan(
			&i.ID,
			&i.CompanyID,
			&i.Code,
			&i.Name,
			&i.Description,
			&i.Type,
			&i.Config,
			&i.Priority,
			&i.Stackable,
			&i.Exclusive,
			&i.StartsAt,
			&i.EndsAt,
			&i.DaysOfWeek,
			&i.TimeFrom,
			&i.TimeTo,
			&i.Status,
			&i.Version,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const touchTerminalSync = `-- name: TouchTerminalSync :exec
UPDATE terminal_sync_tokens SET last_sync_at = now(), last_ip = $1, pending = CASE WHEN $2::int < 0 THEN pending ELSE $2::int END,
    agent_version = CASE WHEN $3::text = '' THEN agent_version ELSE $3::text END,
    snapshot_version = CASE WHEN $4::text = '' THEN snapshot_version ELSE $4::text END
WHERE terminal_id = $5
`

type TouchTerminalSyncParams struct {
	Ip              string    `json:"ip"`
	Pending         int32     `json:"pending"`
	Version         string    `json:"version"`
	SnapshotVersion string    `json:"snapshot_version"`
	TerminalID      uuid.UUID `json:"terminal_id"`
}

func (q *Queries) TouchTerminalSync(ctx context.Context, arg TouchTerminalSyncParams) error {
	_, err := q.db.Exec(ctx, touchTerminalSync,
		arg.Ip,
		arg.Pending,
		arg.Version,
		arg.SnapshotVersion,
		arg.TerminalID,
	)
	return err
}

const updateSaleCustomerPoints = `-- name: UpdateSaleCustomerPoints :exec
UPDATE sales SET points_earned = $2 WHERE id = $1
`

type UpdateSaleCustomerPointsParams struct {
	ID           uuid.UUID `json:"id"`
	PointsEarned int64     `json:"points_earned"`
}

func (q *Queries) UpdateSaleCustomerPoints(ctx context.Context, arg UpdateSaleCustomerPointsParams) error {
	_, err := q.db.Exec(ctx, updateSaleCustomerPoints, arg.ID, arg.PointsEarned)
	return err
}

const upsertTerminalSyncToken = `-- name: UpsertTerminalSyncToken :exec

INSERT INTO terminal_sync_tokens (terminal_id, company_id, token_hash, token_hint) VALUES ($1, $2, $3, $4)
ON CONFLICT (terminal_id) DO UPDATE SET token_hash = EXCLUDED.token_hash, token_hint = EXCLUDED.token_hint, created_at = now(),
    last_sync_at = NULL, snapshot_version = '', pending = 0
`

type UpsertTerminalSyncTokenParams struct {
	TerminalID uuid.UUID `json:"terminal_id"`
	CompanyID  uuid.UUID `json:"company_id"`
	TokenHash  string    `json:"token_hash"`
	TokenHint  string    `json:"token_hint"`
}

// ===== terminal device credential =====
func (q *Queries) UpsertTerminalSyncToken(ctx context.Context, arg UpsertTerminalSyncTokenParams) error {
	_, err := q.db.Exec(ctx, upsertTerminalSyncToken,
		arg.TerminalID,
		arg.CompanyID,
		arg.TokenHash,
		arg.TokenHint,
	)
	return err
}
